from app.core.resources import display_rows

"""Notifications endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "notifications"
router = APIRouter(prefix="/notifications", tags=["Notifications"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.user_code,
       t.title,
       t.body,
       t.channel,
       t.status,
       t.sent_at,
       x.data AS extras
FROM notifications AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'notifications' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.user_code,
       t.title,
       t.body,
       t.channel,
       t.status,
       t.sent_at,
       x.data AS extras
FROM notifications AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'notifications' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO notifications (
    code,
    user_code,
    title,
    body,
    channel,
    status,
    sent_at
)
VALUES (
    %(code)s,
    %(user_code)s,
    %(title)s,
    %(body)s,
    %(channel)s,
    %(status)s,
    %(sent_at)s
)
"""

UPDATE_SQL = """
UPDATE notifications
SET user_code = %(user_code)s,
    title = %(title)s,
    body = %(body)s,
    channel = %(channel)s,
    status = %(status)s,
    sent_at = %(sent_at)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM notifications
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM notification_delivery_attempts WHERE notification_code = %(code)s) THEN 'notification_delivery_attempts'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


PRIVATE_BODY = "Private message - only the recipient can read it"


def visible(data, user, record):
    """The admin sees the whole notification log; everyone else only their own notifications.
    Chat previews stay private to their recipient, even for the admin."""
    from app.core.edit_approvals import is_super_admin

    mine = record.get("user_code") == user["code"]
    if not mine and not is_super_admin(data, user):
        return None
    if not mine and (record.get("thread_code") or record.get("screen") == "messages"):
        return {**record, "body": PRIVATE_BODY}
    return record


def owned(data, user, code):
    """Changing or deleting a notification: the admin, or the person it was sent to."""
    from app.core.edit_approvals import is_super_admin

    record = data["records"].get(TABLE, {}).get(code)
    if not record or (record.get("user_code") != user["code"] and not is_super_admin(data, user)):
        raise HTTPException(404, "Notification not found")


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = [r for r in (visible(data, user, row) for row in display_rows(data, TABLE, query_list(data))) if r]
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    data = request.app.state.store.snapshot()
    record = visible(data, user, query_get(data, code))
    if not record:
        raise HTTPException(404, "Notification not found")
    return record


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        owned(data, user, code)
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        owned(data, user, code)
        service.delete(data, code, user["code"])
